import{_ as a,C as r,o,c as l,a6 as i,E as d,j as e,a as g}from"./chunks/framework.CrjICMdL.js";const c="/rb_cobot_docs_muscat/images/settings/weld-overview.avif",h="/rb_cobot_docs_muscat/images/settings/weld-device.avif",p="/rb_cobot_docs_muscat/images/settings/weld-output.avif",u="/rb_cobot_docs_muscat/images/settings/weld-input.avif",b="/rb_cobot_docs_muscat/images/settings/weld-hardware.avif",m="/rb_cobot_docs_muscat/images/settings/weld-map.avif",N=JSON.parse('{"title":"용접 장치","description":"","frontmatter":{"title":"용접 장치","outline":[2,3]},"headers":[],"relativePath":"manual/settings/welding.md","filePath":"manual/settings/welding.md","lastUpdated":1792396350000}'),x={name:"manual/settings/welding.md"};function y(_,t,v,I,A,D){const n=r("DemoFrame"),s=r("ScenarioSteps");return o(),l("div",null,[t[0]||(t[0]=i('<h1 id="용접-장치" tabindex="-1">용접 장치 <a class="header-anchor" href="#용접-장치" aria-label="Permalink to &quot;용접 장치&quot;">​</a></h1><p><strong>용접 장치</strong> 설정은 로봇이 <strong>용접기와 신호를 주고받는 방법</strong>을 정합니다. 용접기와 연결하는 방식, 용접기로 보내는 신호와 용접기에서 읽는 신호를 연결할 입출력 포트, 사용하는 용접기의 하드웨어 종류, 전류·전압과 아날로그 출력값의 대응을 한 화면에서 설정합니다.</p><p>이 문서에서는 <strong>설정 &gt; 디바이스 &gt; 용접</strong> 화면에서 다음을 해 봅니다.</p><ul><li>용접 장치 ID를 고르고 출력 포트를 연결하기</li><li>하드웨어(프로세스 타입 등)를 고르기</li><li>변환 맵을 추가하고 저장하기</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><p>왼쪽 설정 메뉴의 <strong>디바이스 &gt; 용접</strong>을 누르면 나타나는 화면입니다. 아직 아무것도 바꾸지 않은 상태입니다.</p><p><img src="'+c+'" alt="용접 화면"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>영역</th><th>역할</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td>용접 장치 옵션 설정</td><td>용접기와 연결하는 방식(장치 ID)과 통신 장치의 IP·포트를 정합니다.</td></tr><tr><td style="text-align:center;">②</td><td>용접 출력 옵션 설정</td><td>로봇이 용접기로 보내는 신호를 연결할 출력 포트를 정합니다.</td></tr><tr><td style="text-align:center;">③</td><td>용접 입력 옵션 설정</td><td>용접기가 로봇으로 보내는 신호를 읽을 입력 포트를 정합니다.</td></tr><tr><td style="text-align:center;">④</td><td>용접 하드웨어 옵션 설정</td><td>사용하는 용접기의 프로세스 타입, 와이어 타입·크기, 가스 타입을 고릅니다.</td></tr><tr><td style="text-align:center;">⑤</td><td>용접 변환 맵 설정</td><td>용접 전류·전압 값과 아날로그 출력값(V)의 대응을 표로 정합니다.</td></tr><tr><td style="text-align:center;">⑥</td><td>초기화 · 저장</td><td>다섯 카드의 값을 <strong>한꺼번에</strong> 저장하거나, 저장하지 않은 값을 저장된 값으로 되돌립니다.</td></tr></tbody></table></div><p>화면 위쪽의 <strong>저장</strong>을 눌러야 ①~⑤에서 고른 값이 적용됩니다. <strong>초기화</strong>는 저장하지 않은 값을 저장된 값으로 되돌리며, 화면의 값이 저장된 값과 같으면 눌리지 않습니다.</p><h2 id="용접-장치-1" tabindex="-1">용접 장치 (①) <a class="header-anchor" href="#용접-장치-1" aria-label="Permalink to &quot;용접 장치 (①)&quot;">​</a></h2><p><img src="'+h+'" alt="용접 장치 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">⑦</td><td><strong>장치 ID</strong></td><td>용접기와 연결하는 방식을 고릅니다. 아래에서 자세히 설명합니다.</td></tr><tr><td style="text-align:center;">⑧</td><td><strong>장치 IP</strong></td><td>통신으로 연결하는 용접기의 IP 주소입니다. 네 칸에 각각 0~255를 입력합니다.</td></tr><tr><td style="text-align:center;">⑨</td><td><strong>장치 포트</strong></td><td>통신으로 연결하는 용접기의 포트 번호입니다. 0~65535 범위의 숫자를 입력합니다.</td></tr></tbody></table></div><h3 id="장치-id" tabindex="-1">장치 ID <a class="header-anchor" href="#장치-id" aria-label="Permalink to &quot;장치 ID&quot;">​</a></h3><table tabindex="0"><thead><tr><th>선택</th><th>동작</th></tr></thead><tbody><tr><td><strong>None</strong></td><td>용접기와 통신하지 않습니다. 처음 상태의 기본값입니다.</td></tr><tr><td><strong>I/O Signal</strong></td><td>컨트롤 박스의 디지털·아날로그 입출력 신호로 용접기와 연결합니다. 출력(②)·입력(③) 카드에서 정한 포트를 사용합니다.</td></tr><tr><td><strong>Miller M.Bus</strong></td><td>Modbus 통신으로 연결합니다. 장치 IP·포트로 접속하며, 연결될 때 하드웨어(④)에서 고른 프로세스·와이어·가스 종류를 용접기로 보냅니다.</td></tr><tr><td><strong>Aotai M.Bus</strong></td><td>Modbus 통신으로 연결합니다. 장치 IP·포트로 접속하고 용접기의 상태와 전류·전압·송급 속도를 읽어 옵니다.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">M.Bus의 포트</p><p><strong>Miller M.Bus</strong>나 <strong>Aotai M.Bus</strong>를 고르고 저장하면 장치 포트는 <strong>502</strong>로 저장됩니다. 입력한 포트 값은 쓰이지 않습니다.</p></div><h2 id="용접-출력-2" tabindex="-1">용접 출력 (②) <a class="header-anchor" href="#용접-출력-2" aria-label="Permalink to &quot;용접 출력 (②)&quot;">​</a></h2><p>로봇이 용접기로 보내는 신호를 <strong>컨트롤 박스의 어느 출력 포트에 연결할지</strong> 고릅니다. 장치 ID가 <strong>I/O Signal</strong>일 때 사용합니다. 아래는 아직 아무것도 고르지 않은 상태입니다.</p><p><img src="'+p+'" alt="용접 출력 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th><th>선택지</th></tr></thead><tbody><tr><td style="text-align:center;">⑩</td><td><strong>아크 발생 신호</strong></td><td>아크 용접을 하는 동안 켜집니다.</td><td>None, Digital Output 0~15</td></tr><tr><td style="text-align:center;">⑪</td><td><strong>접촉 신호</strong></td><td>접촉(터치) 동작을 하는 동안 켜집니다.</td><td>None, Digital Output 0~15</td></tr><tr><td style="text-align:center;">⑫</td><td><strong>가스 발생 신호</strong></td><td>가스를 내보내는 동안 켜집니다.</td><td>None, Digital Output 0~15</td></tr><tr><td style="text-align:center;">⑬</td><td><strong>와이어 인칭 신호</strong></td><td>와이어 인칭 동작 중 켜집니다.</td><td>None, Digital Output 0~15</td></tr><tr><td style="text-align:center;">⑭</td><td><strong>와이어 재인칭 신호</strong></td><td>와이어 재인칭(반대 방향) 동작 중 켜집니다.</td><td>None, Digital Output 0~15</td></tr><tr><td style="text-align:center;">⑮</td><td><strong>전류 설정 포트</strong></td><td>용접 전류 설정값을 변환 맵(⑤)으로 바꾼 전압을 내보냅니다.</td><td>None, Analog Output 0~3</td></tr><tr><td style="text-align:center;">⑯</td><td><strong>전압 설정 포트</strong></td><td>용접 전압 설정값을 변환 맵(⑤)으로 바꾼 전압을 내보냅니다.</td><td>None, Analog Output 0~3</td></tr></tbody></table></div><p><strong>None</strong>을 고른 신호는 내보내지 않습니다.</p><h2 id="용접-입력-3" tabindex="-1">용접 입력 (③) <a class="header-anchor" href="#용접-입력-3" aria-label="Permalink to &quot;용접 입력 (③)&quot;">​</a></h2><p>용접기가 로봇으로 보내는 신호를 <strong>컨트롤 박스의 어느 입력 포트로 읽을지</strong> 고릅니다. 장치 ID가 <strong>I/O Signal</strong>일 때 사용합니다.</p><p><img src="'+u+'" alt="용접 입력 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th><th>선택지</th></tr></thead><tbody><tr><td style="text-align:center;">⑰</td><td><strong>용접기 준비 신호</strong></td><td>용접기가 준비되었는지 읽습니다. <strong>None이면 항상 준비된 것으로 봅니다.</strong></td><td>None, Digital Input 0~15</td></tr><tr><td style="text-align:center;">⑱</td><td><strong>아크 발생 피드백</strong></td><td>아크가 발생했는지 읽습니다.</td><td>None, Digital Input 0~15</td></tr><tr><td style="text-align:center;">⑲</td><td><strong>접촉 신호 피드백</strong></td><td>접촉 상태를 읽습니다.</td><td>None, Digital Input 0~15</td></tr><tr><td style="text-align:center;">⑳</td><td><strong>가스 신호 피드백</strong></td><td>가스 상태를 읽습니다.</td><td>None, Digital Input 0~15</td></tr><tr><td style="text-align:center;">㉑</td><td><strong>송급기 신호 피드백</strong></td><td>와이어 송급기 상태를 읽습니다.</td><td>None, Digital Input 0~15</td></tr><tr><td style="text-align:center;">㉒</td><td><strong>용접기 에러 신호</strong></td><td>용접기의 에러 신호를 읽습니다.</td><td>None, Digital Input 0~15</td></tr><tr><td style="text-align:center;">㉓</td><td><strong>전류 피드백</strong></td><td>실제 용접 전류에 해당하는 아날로그 입력을 읽어 변환 맵(⑤)으로 전류 값으로 바꿉니다.</td><td>None, Analog Input 0~3</td></tr><tr><td style="text-align:center;">㉔</td><td><strong>전압 피드백</strong></td><td>실제 용접 전압에 해당하는 아날로그 입력을 읽어 변환 맵(⑤)으로 전압 값으로 바꿉니다.</td><td>None, Analog Input 0~3</td></tr></tbody></table></div><p>용접기 준비 신호를 제외하고, <strong>None</strong>을 고른 신호는 읽지 않고 꺼진 값(전류·전압은 0)으로 처리합니다.</p><h2 id="용접-하드웨어-4" tabindex="-1">용접 하드웨어 (④) <a class="header-anchor" href="#용접-하드웨어-4" aria-label="Permalink to &quot;용접 하드웨어 (④)&quot;">​</a></h2><p>사용하는 용접기의 종류를 고릅니다. 아래는 아직 아무것도 바꾸지 않은 상태입니다. 장치 ID가 <strong>Miller M.Bus</strong>일 때 이 값들이 연결 시 용접기로 전달됩니다.</p><p><img src="'+b+'" alt="용접 하드웨어 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>선택지</th></tr></thead><tbody><tr><td style="text-align:center;">㉕</td><td><strong>프로세스 타입</strong></td><td>CV MIG, Pulse, HD MIG, RMD</td></tr><tr><td style="text-align:center;">㉖</td><td><strong>와이어 타입</strong></td><td>Steel (ER70X), Metal (EXXC), Flux (EXXT), AL (4XXX), AL (4943), AL (5XXX), SS (ER3XX), SS (ER4XX)</td></tr><tr><td style="text-align:center;">㉗</td><td><strong>와이어 크기</strong></td><td>0.8mm, 0.9mm, 1.0mm, 1.2mm (0.045), 1.2mm (3/64), 1.4mm, 1.6mm, 2.0mm, 2.4mm</td></tr><tr><td style="text-align:center;">㉘</td><td><strong>가스 타입</strong></td><td>100% Ar, 98% Ar+2% CO2, 95% Ar+5% CO2, 90% Ar+10% CO2, 85% Ar+15% CO2, 80% Ar+20% CO2, 75% Ar+25% CO2, 100% CO2, 98% Ar+2% O2, 95% Ar+5% O2, 100% He, 75% He+25% Ar, 50% He+50% Ar, 25% He+75% Ar, 81% Ar+18% He+1% CO2, 66% Ar+33% He+1% CO2, 90% He+7.5% Ar+2.5% CO2</td></tr></tbody></table></div><h2 id="용접-변환-맵-5" tabindex="-1">용접 변환 맵 (⑤) <a class="header-anchor" href="#용접-변환-맵-5" aria-label="Permalink to &quot;용접 변환 맵 (⑤)&quot;">​</a></h2><p>변환 맵은 <strong>전류·전압 값</strong>과 **아날로그 입출력 전압(V)**의 대응표입니다. <strong>용접 전류</strong>와 <strong>용접 전압</strong>에 각각 표가 하나씩 있고, 줄마다 <strong>값</strong>(왼쪽 입력칸)과 그에 대응하는 <strong>출력(V)</strong>(오른쪽 입력칸)을 입력합니다. 아래는 전류·전압 맵에 한 줄씩 추가한 상태입니다.</p><p><img src="'+m+'" alt="용접 변환 맵 카드의 구성"></p><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">㉙</td><td><strong>전류 맵 추가</strong></td><td>용접 전류 표에 값이 0인 줄을 추가합니다.</td></tr><tr><td style="text-align:center;">㉚</td><td><strong>전류 (A)</strong> 입력칸</td><td>변환할 값입니다.</td></tr><tr><td style="text-align:center;">㉛</td><td><strong>출력 (V)</strong> 입력칸</td><td>㉚의 값에 대응하는 아날로그 전압입니다.</td></tr><tr><td style="text-align:center;">㉜</td><td>삭제 버튼</td><td>그 줄을 삭제합니다.</td></tr><tr><td style="text-align:center;">㉝</td><td><strong>전압 맵 추가</strong></td><td>용접 전압 표에 줄을 추가합니다. 입력 방식은 전류 표와 같습니다.</td></tr></tbody></table></div><h3 id="변환-방식" tabindex="-1">변환 방식 <a class="header-anchor" href="#변환-방식" aria-label="Permalink to &quot;변환 방식&quot;">​</a></h3><ul><li>값이 줄과 줄 사이에 있으면 두 줄 사이를 <strong>직선으로 보간</strong>한 출력을 사용합니다.</li><li>값이 첫 줄보다 작거나 마지막 줄보다 크면 <strong>가장 가까운 끝 줄의 출력</strong>을 사용합니다.</li><li>줄이 하나뿐이면 항상 그 줄의 출력을 사용합니다. 줄이 없으면 0을 사용합니다.</li><li>입력 포트로 읽는 전류·전압 피드백(㉓, ㉔)은 같은 표를 <strong>반대로</strong> 적용해 출력(V)에서 값을 구합니다.</li><li>줄은 입력한 순서와 관계없이 <strong>저장하면 값 기준 오름차순으로 정렬</strong>되어 다시 표시됩니다.</li></ul><div class="warning custom-block"><p class="custom-block-title">줄은 10개까지 저장됩니다</p><p>화면에서는 전류·전압 각각 16줄까지 추가할 수 있지만, <strong>10줄을 넘으면 저장되지 않고</strong> &quot;Set Welding Error&quot; 오류 창이 표시됩니다. 전류와 전압 표 각각 10줄 이하로 입력하세요.</p></div><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2>',37)),d(n,{id:"settings-welding"}),t[1]||(t[1]=e("h2",{id:"사용-방법",tabindex:"-1"},[g("사용 방법 "),e("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),t[2]||(t[2]=e("p",null,"장치 ID를 I/O Signal로 고르고 아크 발생 신호 포트와 프로세스 타입을 정한 뒤, 전류 맵에 한 줄을 추가해 저장하는 과정입니다.",-1)),d(s,{id:"settings-welding"}),t[3]||(t[3]=e("div",{class:"tip custom-block"},[e("p",{class:"custom-block-title"},"저장에 실패하면"),e("p",null,'저장하지 못하면 "Set Welding Error"로 시작하는 오류 창이 표시되고 화면의 값은 저장되지 않습니다. 포트 번호나 IP·포트 값이 범위를 벗어났는지, 변환 맵이 10줄을 넘지 않는지 확인하세요.')],-1))])}const O=a(x,[["render",y]]);export{N as __pageData,O as default};
